        <style key="h6" dangerouslySetInnerHTML={{ __html: "\n/* layout: fixed left rail of sections, content area of stat tiles, charts and tables */\n:root{--bg:#f1f3f7;--panel:#ffffff;--ink:#121a2e;--ink2:#3c4558;--soft:#6a7387;--line:#e3e7ee;--navy:#0f1f40;--red:#c8323a;--D:#2557a8;--good:#1f7a4a;--warn:#9a5b00;--bad:#b42318;--sel:#e8edf6;\n--ui:\"Schibsted Grotesk\",-apple-system,Segoe UI,Arial,sans-serif;--num:\"Barlow Condensed\",\"Schibsted Grotesk\",Arial,sans-serif}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#0c111b;--panel:#151c2a;--ink:#e9edf4;--ink2:#c3cad8;--soft:#97a0b2;--line:#263044;--sel:#1e2840;--good:#4fc184;--warn:#e0a34a;--bad:#f07167;color-scheme:dark}}\n:root[data-theme=\"dark\"]{--bg:#0c111b;--panel:#151c2a;--ink:#e9edf4;--ink2:#c3cad8;--soft:#97a0b2;--line:#263044;--sel:#1e2840;--good:#4fc184;--warn:#e0a34a;--bad:#f07167;color-scheme:dark}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 var(--ui)}\na{color:var(--D)}\nbutton{font:inherit;cursor:pointer}\n.rail{position:fixed;inset:0 auto 0 0;width:236px;background:var(--navy);color:#fff;padding:18px 12px;display:flex;flex-direction:column;gap:4px;z-index:5}\n.brand{font:800 17px var(--ui);padding:4px 10px 16px;display:flex;align-items:center;gap:8px}.brand b{background:var(--red);padding:2px 7px;border-radius:5px}.brand em{font-style:normal;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;opacity:.7}\n.nav{border:0;background:none;color:#c9d3e8;text-align:left;padding:10px 12px;border-radius:10px;font-weight:600;display:flex;justify-content:space-between;align-items:center}\n.nav:hover{background:rgba(255,255,255,.07);color:#fff}.nav[aria-current=\"page\"]{background:rgba(255,255,255,.13);color:#fff}\n.nav i{font-style:normal;font-size:12px;background:var(--red);color:#fff;border-radius:999px;padding:1px 8px}\n.rail .me{margin-top:auto;font-size:12.5px;color:#9fb0cf;padding:10px;border-top:1px solid rgba(255,255,255,.1);word-break:break-all}\n.rail .me button{background:none;border:0;color:#fff;padding:0;text-decoration:underline;margin-top:4px}\nmain{margin-left:236px;padding:26px 32px 60px;max-width:1500px}\n@media (max-width:860px){.rail{position:static;width:auto;flex-direction:row;flex-wrap:wrap;padding:10px}.brand{width:100%;padding-bottom:6px}.rail .me{display:none}main{margin-left:0;padding:18px 16px 40px}.nav{padding:8px 10px}}\nh1{font:800 28px/1.15 var(--ui);margin:0 0 4px}\n.sub{color:var(--soft);margin:0 0 20px}\nh2{font:800 17px var(--ui);margin:26px 0 10px}\n.tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px}\n.tile{background:var(--panel);border-radius:14px;padding:14px 16px;display:flex;flex-direction:column;gap:2px}\n.tile span{font-size:12.5px;color:var(--soft);font-weight:600}.tile b{font:700 32px/1.05 var(--num);font-variant-numeric:tabular-nums}.tile small{font-size:12.5px;color:var(--soft)}\n.tile.hl b{color:var(--good)}.tile.warn b{color:var(--warn)}.tile.bad b{color:var(--bad)}\n@media (min-width:1100px){.tiles{grid-template-columns:repeat(4,minmax(0,1fr))}}\n.card{background:var(--panel);border-radius:14px;padding:16px 18px}\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:14px}\n.chart svg{width:100%;height:160px;display:block}\n.chart .cap{font-size:12.5px;color:var(--soft);margin-top:6px;display:flex;justify-content:space-between}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth{text-align:left;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:var(--soft);font-weight:700;padding:10px 10px;border-bottom:1px solid var(--line);white-space:nowrap}\ntd{padding:10px;border-bottom:1px solid var(--line);vertical-align:top}\ntr:last-child td{border-bottom:0}\n.tbl{background:var(--panel);border-radius:14px;overflow-x:auto}\n.rm-area{margin:0 0 14px}.rm-area h2{display:flex;justify-content:space-between;align-items:baseline;gap:10px;font-size:18px;margin:0 0 8px}.rm-area h2 small{font-size:13px;color:var(--soft);font-weight:600}\n.rm-bar{height:6px;background:var(--line);border-radius:3px;margin:0 0 10px;overflow:hidden}.rm-bar i{display:block;height:6px;background:var(--good)}\n.rm-row{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:4px 10px;align-items:start;padding:10px 0;border-top:1px solid var(--line)}\n.rm-row.done .rm-t{text-decoration:line-through;color:var(--soft)}.rm-t{font-weight:700}.rm-d{grid-column:2/-1;color:var(--ink2);font-size:13.5px}\n.rm-ctl{display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end}.rm-ctl select{padding:4px 8px;font-size:13px}\n.rm-ck{width:22px;height:22px;border-radius:6px;border:2px solid var(--soft);background:var(--panel);padding:0;display:grid;place-items:center;color:#fff;font-size:14px;line-height:1}.rm-ck.on{background:var(--good);border-color:var(--good)}\n.p-crit{background:color-mix(in srgb,var(--bad) 14%,transparent);color:var(--bad)}.p-high{background:color-mix(in srgb,var(--warn) 16%,transparent);color:var(--warn)}.p-auto{background:var(--sel);color:var(--ink2)}\n.pill{display:inline-block;font-size:12px;font-weight:700;border-radius:999px;padding:2px 9px;white-space:nowrap}\n.p-pro{background:color-mix(in srgb,var(--good) 15%,transparent);color:var(--good)}\n.p-trial{background:color-mix(in srgb,var(--D) 15%,transparent);color:var(--D)}\n.p-comp{background:color-mix(in srgb,var(--warn) 16%,transparent);color:var(--warn)}\n.p-free{background:var(--sel);color:var(--ink2)}\n.p-bad{background:color-mix(in srgb,var(--bad) 14%,transparent);color:var(--bad)}\n.bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px}\ninput[type=search],input[type=text],input[type=email],input[type=date],input[type=password],textarea,select{font:inherit;background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:10px;padding:9px 12px}\ninput[type=search]{min-width:260px;flex:1;max-width:420px}\ntextarea{width:100%;min-height:70px}\n.btn{border:0;border-radius:10px;padding:9px 14px;font-weight:700;background:var(--navy);color:#fff}\n.btn.sm{padding:5px 10px;font-size:13px}.btn.ghost{background:var(--sel);color:var(--ink)}.btn.red{background:var(--bad)}\n.seg{display:inline-flex;background:var(--sel);border-radius:10px;padding:3px}.seg button{border:0;background:none;padding:6px 12px;border-radius:8px;font-weight:600;color:var(--ink2)}.seg button[aria-pressed=\"true\"]{background:var(--panel);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.08)}\n.muted{color:var(--soft);font-size:13px}\n.empty{padding:28px;text-align:center;color:var(--soft)}\n.row-actions{display:flex;gap:6px;flex-wrap:wrap}\n.toast{position:fixed;right:18px;bottom:18px;background:var(--ink);color:var(--bg);padding:10px 16px;border-radius:10px;font-weight:600;opacity:0;transform:translateY(8px);transition:.2s;z-index:20}.toast.on{opacity:1;transform:none}\n.login{min-height:100vh;display:grid;place-items:center;padding:16px}\n.login form{background:var(--panel);border-radius:18px;padding:28px;width:100%;max-width:380px;display:flex;flex-direction:column;gap:12px}\n.login .brand{color:var(--ink);padding:0 0 8px}\n.linkbtn{background:none;border:0;padding:0;color:inherit;text-decoration:underline;cursor:pointer;font:inherit}\n.err{color:var(--bad);font-size:13.5px;min-height:1em}\n.kv{display:grid;grid-template-columns:auto 1fr;gap:6px 16px;font-size:14px}.kv span{color:var(--soft)}\n.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}.dot.ok{background:var(--good)}.dot.no{background:var(--bad)}.dot.run{background:var(--warn)}\n:focus-visible{outline:3px solid #2557a8;outline-offset:2px}\n" }} />
